import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"systemd 显示 active，为什么数据链仍然是死的","description":"复盘服务进程正常但下游无限重连的问题，并建立从 liveness、readiness、数据率到相对启动时序的板端验收方法","frontmatter":{"title":"systemd 显示 active，为什么数据链仍然是死的","description":"复盘服务进程正常但下游无限重连的问题，并建立从 liveness、readiness、数据率到相对启动时序的板端验收方法","tags":["Linux","systemd","ROS","Health Check","问题复盘"],"date":"2026/07/20"},"headers":[],"relativePath":"linux/service-active-not-ready.md","filePath":"linux/service-active-not-ready.md","lastUpdated":1784519165000}'),n={name:"linux/service-active-not-ready.md"};function r(o,e,l,c,d,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="systemd-显示-active-为什么数据链仍然是死的" tabindex="-1">systemd 显示 active，为什么数据链仍然是死的 <a class="header-anchor" href="#systemd-显示-active-为什么数据链仍然是死的" aria-label="Permalink to &quot;systemd 显示 active，为什么数据链仍然是死的&quot;">​</a></h1><p><code>systemctl is-active</code> 返回 <code>active</code>，只说明 systemd 认为主进程还活着。它不证明相机已经出帧、Unix socket 正在提供数据、下游完成握手，更不证明 topic 达到目标频率。</p><p>这次故障里，上游相机服务一直是 active，下游视觉服务却无限重连。真正的问题藏在两组看似合法、组合后却不可能工作的配置里。</p><h2 id="现场症状" tabindex="-1">现场症状 <a class="header-anchor" href="#现场症状" aria-label="Permalink to &quot;现场症状&quot;">​</a></h2><p>系统启动后：</p><ul><li>相机服务为 <code>active (running)</code>；</li><li>下游进程也没有立即退出；</li><li>客户端日志持续显示 socket reconnect；</li><li>预期的图像输入始终没有建立；</li><li>IMU 等其他接口仍然正常，容易让人误判为“偶发启动顺序问题”。</li></ul><p>第一反应通常是增加 <code>RestartSec</code>、延长启动延迟或让客户端无限重试。但这些操作只会延后暴露根因。</p><h2 id="错误判断-把进程存活当成服务可用" tabindex="-1">错误判断：把进程存活当成服务可用 <a class="header-anchor" href="#错误判断-把进程存活当成服务可用" aria-label="Permalink to &quot;错误判断：把进程存活当成服务可用&quot;">​</a></h2><p>systemd 默认关注的是进程生命周期。对于 <code>Type=simple</code> 服务，只要进程成功启动且没有退出，unit 就可以进入 active 状态。</p><p>业务 readiness 是另一回事。相机流水线至少要满足：</p><ol><li>设备已经成功打开；</li><li>必需的硬件处理链已经创建；</li><li>目标输出模式确实启用；</li><li>socket 或输出端口完成监听；</li><li>下游能收到格式、尺寸和时间戳都正确的数据。</li></ol><p>缺少任何一步，进程都可能仍然活着。</p><h2 id="证据链-不要先改重试次数" tabindex="-1">证据链：不要先改重试次数 <a class="header-anchor" href="#证据链-不要先改重试次数" aria-label="Permalink to &quot;证据链：不要先改重试次数&quot;">​</a></h2><p>排查顺序应该从 producer 到 consumer：</p><h3 id="_1-核对最终生效配置" tabindex="-1">1. 核对最终生效配置 <a class="header-anchor" href="#_1-核对最终生效配置" aria-label="Permalink to &quot;1. 核对最终生效配置&quot;">​</a></h3><p>这次配置允许“启用下游 DMA-BUF consumer”，同时“关闭生成完整 atlas 所必需的硬件处理”。两个开关单独看都合法，组合起来却意味着 consumer 永远等不到目标输出。</p><p>如果配置系统只校验字段类型，不校验跨字段约束，故障就会被推迟到 runtime。</p><h3 id="_2-检查-producer-是否真的创建输出" tabindex="-1">2. 检查 producer 是否真的创建输出 <a class="header-anchor" href="#_2-检查-producer-是否真的创建输出" aria-label="Permalink to &quot;2. 检查 producer 是否真的创建输出&quot;">​</a></h3><p>不要只看服务日志里的“started”。需要确认：输出 socket 是否创建、类型是否正确、owner/mode 是否符合预期、producer 是否真的进入 publish loop。</p><h3 id="_3-检查-consumer-重连的相对时序" tabindex="-1">3. 检查 consumer 重连的相对时序 <a class="header-anchor" href="#_3-检查-consumer-重连的相对时序" aria-label="Permalink to &quot;3. 检查 consumer 重连的相对时序&quot;">​</a></h3><p>记录 producer 启动、socket listen、首帧、consumer connect、首个有效数据之间的单调时间。这样才能区分“启动较慢”和“永远不会 ready”。</p><h3 id="_4-最后看业务输出" tabindex="-1">4. 最后看业务输出 <a class="header-anchor" href="#_4-最后看业务输出" aria-label="Permalink to &quot;4. 最后看业务输出&quot;">​</a></h3><p>对于 ROS 或流式系统，至少检查 topic 是否存在、频率是否达到合同、时间戳是否推进、序列号是否连续。服务 active 不能替代这些证据。</p><h2 id="根因与修复" tabindex="-1">根因与修复 <a class="header-anchor" href="#根因与修复" aria-label="Permalink to &quot;根因与修复&quot;">​</a></h2><p>根因是缺少配置级 capability gate。修复后，在服务真正启动硬件链之前就验证：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enable_direct_consumer = true</span></span>
<span class="line"><span>  ⇒ enable_required_transform = true</span></span>
<span class="line"><span>  ⇒ output_layout = full_atlas</span></span></code></pre></div><p>不满足时立即失败，并输出可读的配置错误，不能让下游进入无限重连。</p><p>socket 清理也必须谨慎。启动时不能对一个可配置路径无条件 <code>unlink</code>，需要先检查文件类型、owner 和当前是否存在活跃 listener，避免删除了不属于本服务的对象。</p><h2 id="怎样建立真正的-readiness" tabindex="-1">怎样建立真正的 readiness <a class="header-anchor" href="#怎样建立真正的-readiness" aria-label="Permalink to &quot;怎样建立真正的 readiness&quot;">​</a></h2><p>有条件时可以使用 <code>Type=notify</code>，由进程在完成设备初始化、输出端建立和首轮自检后发送 <code>READY=1</code>。但这仍只是进程内部 readiness，外部 health check 还应补充：</p><ul><li>输出端口或 socket 可连接；</li><li>首帧在超时内到达；</li><li>topic/rate 位于允许范围；</li><li>关键时间戳和 sequence 持续推进；</li><li>consumer 重连次数没有持续增长。</li></ul><h2 id="修复后的验收" tabindex="-1">修复后的验收 <a class="header-anchor" href="#修复后的验收" aria-label="Permalink to &quot;修复后的验收&quot;">​</a></h2><p>验收不应该只写“服务已恢复”。更可靠的记录是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>T0      systemd 启动 producer</span></span>
<span class="line"><span>T0+Δ1   设备与硬件处理链 ready</span></span>
<span class="line"><span>T0+Δ2   socket 开始监听</span></span>
<span class="line"><span>T0+Δ3   consumer 连接成功</span></span>
<span class="line"><span>T0+Δ4   首个有效 frame 到达</span></span>
<span class="line"><span>steady  topic/rate/sequence 持续满足合同</span></span></code></pre></div><p>同时还要测试两条失败路径：配置组合非法时必须启动失败；producer 重启后 consumer 必须能够重新建立连接，并且不会读到旧 socket 或旧 buffer。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p><code>active</code> 是 liveness，不是 readiness，更不是数据面健康。涉及相机、NPU、VINS、串口或网络流时，完成线必须延伸到真实输出、频率、时间戳和重连行为。</p><p>参考：<code>READY=1</code> 的语义见 <a href="https://www.freedesktop.org/software/systemd/man/latest/sd_notify.html" target="_blank" rel="noreferrer">sd-daemon 官方接口说明</a>。</p>`,38)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
